<script setup>
import {ref,onMounted} from 'vue';import {api} from './api.js';
const mode=ref('signin'),show=ref(false),busy=ref(false),message=ref(''),user=ref(null),items=ref([]),challenge=ref(null);const form=ref({name:'',email:'',password:'',code:'',token:''});const editor=ref({title:'',summary:'',content:'',imageUrl:'',status:'PUBLISHED'});
async function act(fn){busy.value=true;message.value='';try{await fn()}catch(e){message.value=e.message}finally{busy.value=false}}
const signin=()=>act(async()=>{challenge.value=(await api('/auth/signin',{method:'POST',body:JSON.stringify({email:form.value.email,password:form.value.password})})).challenge;mode.value='verify';message.value='Periksa email untuk kode 6 digit.'});
const verify=()=>act(async()=>{const d=await api('/auth/verify-2fa',{method:'POST',body:JSON.stringify({userId:challenge.value.userId,code:form.value.code})});localStorage.setItem('token',d.token);user.value=d.user;await load();});
const signup=()=>act(async()=>{message.value=(await api('/auth/signup',{method:'POST',body:JSON.stringify(form.value)})).message;mode.value='signin'});
const forgot=()=>act(async()=>{message.value=(await api('/auth/forgot-password',{method:'POST',body:JSON.stringify({email:form.value.email})})).message;mode.value='reset'});
const reset=()=>act(async()=>{message.value=(await api('/auth/reset-password',{method:'POST',body:JSON.stringify({token:form.value.token,password:form.value.password})})).message;mode.value='signin'});
async function load(){items.value=await api('/publications')};async function mark(id,type){await api(`/publications/${id}/${type}`,{method:'POST'});await load()};
const publish=()=>act(async()=>{await api('/publications',{method:'POST',body:JSON.stringify(editor.value)});editor.value={title:'',summary:'',content:'',imageUrl:'',status:'PUBLISHED'};await load();message.value='Informasi tersimpan dan notifikasi diproses.'});
function logout(){localStorage.removeItem('token');user.value=null;items.value=[];mode.value='signin'}
onMounted(()=>{if(localStorage.getItem('token'))act(async()=>{user.value=await api('/auth/me');await load()})});
</script>
<template><main><header><div><b>Pusat Info</b><span>Portal informasi karyawan</span></div><button v-if="user" class="ghost" @click="logout">Keluar</button></header>
<section v-if="!user" class="auth card"><h1>{{mode==='signin'?'Masuk':mode==='signup'?'Daftar akun':mode==='forgot'?'Lupa kata sandi':mode==='reset'?'Atur ulang kata sandi':'Verifikasi bahwa ini Anda'}}</h1><p class="muted">Akses informasi resmi dan konfirmasi pemahaman Anda.</p>
<form @submit.prevent="mode==='signin'?signin():mode==='signup'?signup():mode==='forgot'?forgot():mode==='reset'?reset():verify()"><input v-if="mode==='signup'" v-model="form.name" placeholder="Nama lengkap" required><input v-if="!['verify','reset'].includes(mode)" v-model="form.email" type="email" placeholder="Email" required><input v-if="['signin','signup','reset'].includes(mode)" v-model="form.password" :type="show?'text':'password'" placeholder="Kata sandi minimal 10 karakter" required><label v-if="['signin','signup','reset'].includes(mode)" class="check"><input type="checkbox" v-model="show"> Tampilkan kata sandi</label><input v-if="mode==='verify'" v-model="form.code" inputmode="numeric" maxlength="6" placeholder="Kode 6 digit" required><input v-if="mode==='reset'" v-model="form.token" placeholder="Token dari email" required><button :disabled="busy">{{busy?'Memproses...':'Lanjutkan'}}</button></form><p class="notice" v-if="message">{{message}}</p><nav><button class="link" @click="mode='signin'">Sign in</button><button class="link" @click="mode='signup'">Sign up</button><button class="link" @click="mode='forgot'">Forget password</button></nav></section>
<section v-else><div class="hero"><div><p>Halo, {{user.name}}</p><h1>Informasi yang perlu Anda ketahui</h1></div><span class="badge">{{user.role}}</span></div><p class="notice" v-if="message">{{message}}</p>
<form v-if="user.role==='ADMIN'" class="card editor" @submit.prevent="publish"><h2>Terbitkan informasi</h2><input v-model="editor.title" placeholder="Judul" required><input v-model="editor.summary" placeholder="Ringkasan" required><input v-model="editor.imageUrl" placeholder="URL gambar (opsional)"><textarea v-model="editor.content" placeholder="Isi informasi" required></textarea><select v-model="editor.status"><option>PUBLISHED</option><option>DRAFT</option></select><button>Simpan</button></form>
<div class="grid"><article v-for="x in items" :key="x.id" class="card publication"><img v-if="x.imageUrl" :src="x.imageUrl" :alt="x.title"><div v-else class="character">📖</div><small>{{x.status}} • {{new Date(x.createdAt).toLocaleDateString('id-ID')}}</small><h2>{{x.title}}</h2><p>{{x.summary}}</p><details><summary>Baca selengkapnya</summary><p class="content">{{x.content}}</p></details><div class="actions"><button :class="{done:x.myProgress?.readAt}" @click="mark(x.id,'read')">✓ Sudah dibaca</button><button :class="{done:x.myProgress?.understoodAt}" @click="mark(x.id,'understood')">✓ Sudah dipahami</button></div><div class="stats"><b>Dibaca ({{x.readers.length}})</b><span>{{x.readers.map(u=>u.name).join(', ')||'Belum ada'}}</span><b>Dipahami ({{x.understoodBy.length}})</b><span>{{x.understoodBy.map(u=>u.name).join(', ')||'Belum ada'}}</span></div></article></div></section></main></template>
